class Main {
  static int sum(int n) {
    if (n < 0 || n > 100)
      throw new IllegalArgumentException();
    if (n == 0)
      return 0;
    int smaller = sum(n - 1);
    return smaller + n;
  }
  public static void main(String[] args) {
    System.out.println(sum(101));
  }
}

public static int factorial(int n) {
    if (n < 0 || n > 12)
        throw new IllegalArgumentException();

    if (n == 0)
        return 1;

    int smaller = factorial(n - 1);
    return smaller * n;
}

class Main {
  static void increase(int[] a, int n) {
    if (n == 0) return;
    a[0] = a[0] + 1;
    increase(a, n - 1);
  }
  public static void main(String[] args) {
    int[] values = {0};
    increase(values, 2);
    System.out.println(values[0]);
  }
}

