class Main {
  static int sum(int n) {
    if (n == 0) return 0;
    return sum(n - 1) + n;
  }
  static int factorial(int n) {
    if (n == 0) return 1;
    return factorial(n - 1) * n;
  }
  public static void main(String[] args) {
    System.out.println(sum(3) + factorial(3));
  }
}
